    expect(await ui.bulkSettle(pg_wes, [c_ben_0, c_ada_1])).toEqual({ settled: 1, refused: 1 });
    expect(await ui.bulkSettle(pg_wes, [c_ada_0])).toEqual({ settled: 0, refused: 1 });
